------------ lifeCycle ------------

function LadderStruggleBattleEnd:InitRoundAndScore()
    local mgr = LadderStruggleMgr
    local round = mgr.struggleNextSessionIndex - 1
    local resultData = mgr.struggleData

    local scoreL = 0
    local scoreR = 0
    self.SImg_Round1.Status = 3
    self.SImg_Round2.Status = 3
    self.SImg_Round3.Status = 3
    for i = 1, round, 1 do
        local waveData = resultData[i]
        local state = waveData.win == true and 1 or 2
        scoreL = scoreL + (waveData.win == true and 1 or 0)
        scoreR = scoreR + (waveData.win == true and 0 or 1)
        if i == 1 then
            self.SImg_Round3.Status = state
        elseif i == 2 then
            self.SImg_Round2.Status = state
        elseif i == 3 then
            self.SImg_Round1.Status = state
        end
    end

    self.Txt_Score.text = string.format("<color=#01F3E7>%d</color>:%d", scoreL, scoreR)
    -- print("[结算] 大乱斗", round)
end

return LadderStruggleBattleEnd


